// ---------- 14. Last message status tracking for chat list ----------
(function patchMessageSendForStatus() {
  // Patch key message send locations to store lastMessageSenderId and lastMessageStatus
  const senders = ["sendMessage"];
  // We already patched sendMessage, now we need to also set the status on the directChat doc
  // This is done by patching the message listener that updates lastMessage
  const origUpdateLastMessage = (chatId, chatType, text, senderId) => {
    const collection = chatType === "group" ? "groups" : "directChats";
    const update = {
      lastMessage: text,
      lastMessageTime: firebase.firestore.FieldValue.serverTimestamp(),
      lastMessageSenderId: senderId || currentUser?.uid || "",
    };
    // Also determine status (for own messages, it's "sent" initially)
    if (senderId === currentUser?.uid) {
      update.lastMessageStatus = "sent";
    }
    db.collection(collection).doc(chatId).set(update, { merge: true }).catch(() => {});
  };
  window._tcUpdateLastMessage = origUpdateLastMessage;

  // Now hook into the chat data snapshot listener to update status
  // We'll add a flag to items when building chat list
  const origBuildDirect = buildDirectChatItems;
  buildDirectChatItems = async function() {
    const items = await origBuildDirect.call(this);
    // Enrich with lastMessageSentByMe + lastMessageStatus
    for (const item of items) {
      const chatData = item.chatData || {};
      item.lastMessageSentByMe = chatData.lastMessageSenderId === currentUser?.uid;
      item.lastMessageStatus = chatData.lastMessageStatus || "sent";
    }
    return items;
  };

  const origBuildGroup = buildGroupChatItems;
  buildGroupChatItems = async function() {
    const items = await origBuildGroup.call(this);
    // Group items don't have lastMessageSenderId yet - enrich from group data
    for (const item of items) {
      // For groups, we just mark as not-sent-by-me (no status shown unless we query)
      item.lastMessageSentByMe = false;
      item.lastMessageStatus = "";
    }
    return items;
  };
})();

/* ═══════════════════════════════════════════════════════════════════
   WHATSAPP-PARITY CALL FEATURE PACK — 2026
   Adds to existing call system:
   1. Live network quality indicator (RTCPeerConnection.getStats)
   2. Per-tile speaking indicators (AudioContext RMS level)
   3. Group tile tap-to-pin (enlarges to main view, strip for rest)
   4. Long-press tile → participant context menu (mute/pin/remove)
   5. Incoming video call dual accept: Audio-only + Video buttons
   6. Raised hand (group calls) synced via Firestore
   7. Per-tile network quality badges
   8. Responsive for all screen sizes (web, PWA, Capacitor Android)
   All implemented as non-breaking patches over existing functions.
═══════════════════════════════════════════════════════════════════ */
(function CallFeaturePack() {
  "use strict";

  /* ── tiny helpers ──────────────────────────── */
  const $  = id  => document.getElementById(id);
  const qs = (s, r) => (r || document).querySelector(s);
  const qsa = (s, r) => [...(r || document).querySelectorAll(s)];

  /* ══════════════════════════════════════════════════════════════
     1.  NETWORK QUALITY MONITOR
         Polls every 2.5 s via RTCPeerConnection.getStats().
         Shows 4-bar indicator (good/fair/poor) + RTT label.
  ══════════════════════════════════════════════════════════════ */
  let _nqTimer    = null;
  let _nqRafQueue = [];
  const RTT_GOOD  = 120;   // ms
  const RTT_FAIR  = 300;
  const LOSS_GOOD = 1.5;   // %
  const LOSS_FAIR = 7;
  const JIT_GOOD  = 30;    // ms
  const JIT_FAIR  = 80;

  function _getActivePCs() {
    const list = [];
    if (typeof peerConnection !== "undefined" && peerConnection?.connectionState)
      list.push(peerConnection);
    if (typeof groupCallPeerConnections !== "undefined")
      groupCallPeerConnections.forEach(pc => pc?.connectionState && list.push(pc));
    return list;
  }

  async function _sampleQuality() {
    const pcs = _getActivePCs();
    if (!pcs.length) return null;
    let rttSum = 0, lossSum = 0, jitSum = 0, n = 0;
    for (const pc of pcs) {
      try {
        const stats = await pc.getStats();
        stats.forEach(r => {
          if (r.type === "candidate-pair" && r.state === "succeeded" && r.nominated) {
            if (r.currentRoundTripTime != null) { rttSum += r.currentRoundTripTime * 1000; n++; }
          }
          if (r.type === "inbound-rtp" && r.kind === "audio") {
            const tot = (r.packetsReceived || 0) + (r.packetsLost || 0);
            if (tot > 0) lossSum += (r.packetsLost / tot) * 100;
            if (r.jitter != null) jitSum += r.jitter * 1000;
          }
        });
      } catch {}
    }
    return n ? { rtt: rttSum / n, loss: lossSum, jitter: jitSum } : null;
  }

  function _qualityOf(s) {
    if (!s) return "unknown";
    if (s.rtt < RTT_GOOD && s.loss < LOSS_GOOD && s.jitter < JIT_GOOD) return "good";
    if (s.rtt < RTT_FAIR && s.loss < LOSS_FAIR && s.jitter < JIT_FAIR) return "fair";
    return "poor";
  }

  function _ensureNQEl() {
    if ($("_nqInd")) return $("_nqInd");
    const shell = qs(".call-shell");
    if (!shell) return null;
    const el = document.createElement("div");
    el.id   = "_nqInd";
    el.className = "call-network-indicator";
    el.setAttribute("aria-label", "Network quality");
    el.innerHTML =
      `<div class="call-network-indicator-bars">` +
      `<div class="call-network-bar"></div>`.repeat(4) +
      `</div><span class="_nq-lbl"></span>`;
    shell.appendChild(el);
    return el;
  }

  function _updateNQUI(quality, sample) {
    const el = _ensureNQEl();
    if (!el) return;
    el.className = "call-network-indicator " + (quality === "unknown" ? "" : quality);
    const bars = qsa(".call-network-bar", el);
    const fill = { good: 4, fair: 2, poor: 1, unknown: 0 }[quality] ?? 0;
    bars.forEach((b, i) => b.classList.toggle("active", i < fill));
    const lbl = qs("._nq-lbl", el);
    if (lbl) lbl.textContent = sample ? Math.round(sample.rtt) + " ms" : "";
  }

  async function _nqPoll() {
    const s = await _sampleQuality();
    _updateNQUI(_qualityOf(s), s);
    // Per-tile quality badges for group calls
    _updateGroupTileQuality();
  }

  function startNetworkQualityMonitor() {
    stopNetworkQualityMonitor();
    _ensureNQEl();
    _nqTimer = setInterval(_nqPoll, 2500);
    _nqPoll();
  }

  function stopNetworkQualityMonitor() {
    clearInterval(_nqTimer);
    _nqTimer = null;
    $("_nqInd")?.remove();
  }

  /* ══════════════════════════════════════════════════════════════
     2.  SPEAKING INDICATORS
         AudioContext RMS analysis per participant stream.
         Adds pulsing green border when speaking.
  ══════════════════════════════════════════════════════════════ */
  const _speakMap = new Map();   // key → { ctx, raf, stopped }
  const SPEAK_THRESH = 11;       // 0–255 RMS

  function _attachSpeaking(tile, stream, key) {
    if (!stream || !key || !tile) return;
    _detachSpeaking(key);
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      const ctx    = new AC({ sampleRate: 8000 });
      const src    = ctx.createMediaStreamSource(stream);
      const an     = ctx.createAnalyser();
      an.fftSize   = 256;
      src.connect(an);
      const buf  = new Uint8Array(an.frequencyBinCount);
      let rafId;
      const entry = { ctx, rafId: null, stopped: false };
      const loop = () => {
        if (entry.stopped) return;
        an.getByteTimeDomainData(buf);
        let sq = 0;
        for (let i = 0; i < buf.length; i++) { const v = buf[i] - 128; sq += v * v; }
        const rms = Math.sqrt(sq / buf.length);
        tile.classList.toggle("speaking", rms > SPEAK_THRESH);
        entry.rafId = requestAnimationFrame(loop);
      };
      entry.rafId = requestAnimationFrame(loop);
      _speakMap.set(key, entry);
    } catch {}
  }

  function _detachSpeaking(key) {
    const e = _speakMap.get(key);
    if (!e) return;
    e.stopped = true;
    cancelAnimationFrame(e.rafId);
    try { e.ctx.close(); } catch {}
    _speakMap.delete(key);
  }

  function stopAllSpeaking() {
    _speakMap.forEach((_, k) => _detachSpeaking(k));
  }

  /* ══════════════════════════════════════════════════════════════
     3.  GROUP TILE PINNING
         Single tap → pin tile to main stage, others to strip.
         Double-tap or tap X → unpin.
  ══════════════════════════════════════════════════════════════ */
  let _pinnedUid = null;

  function pinGroupCallTile(userId) {
    const grid = $("groupCallGrid");
    if (!grid) return;
    if (_pinnedUid === userId) { unpinGroupCallTile(); return; }
    _pinnedUid = userId;

    // Ensure speaker view is active
    const stage = qs(".call-video-stage");
    if (stage && !stage.classList.contains("speaker-view")) {
      stage.classList.add("speaker-view");
      try { isSpeakerView = true; } catch {}
      const vb = $("toggleViewBtn");
      if (vb) { vb.textContent = "Grid"; vb.title = "Switch to grid view"; }
    }

    // Reclassify tiles
    qsa(".group-call-tile", grid).forEach(t => {
      const mine = t.dataset.userId === userId;
      t.classList.toggle("pinned-main", mine);
      t.classList.toggle("pinned-strip", !mine);
      if (mine) grid.prepend(t);
    });

    // Unpin button
    if (!$("_unpinBtn")) {
      const btn = document.createElement("button");
      btn.id = "_unpinBtn";
      btn.className = "_unpin-btn";
      btn.innerHTML = "&#10005; Unpin";
      btn.onclick = unpinGroupCallTile;
      stage?.appendChild(btn);
    }

    // Expand pinned tile video to fill
    const pinned = qs(".group-call-tile.pinned-main", grid);
    const vid = pinned?.querySelector("video");
    if (vid) { vid.style.objectFit = "cover"; }
  }

  function unpinGroupCallTile() {
    const grid = $("groupCallGrid");
    _pinnedUid = null;
    $("_unpinBtn")?.remove();
    if (!grid) return;
    qsa(".group-call-tile", grid).forEach(t => {
      t.classList.remove("pinned-main", "pinned-strip");
    });
  }

  /* ══════════════════════════════════════════════════════════════
     4.  PARTICIPANT CONTEXT MENU
         Long-press (≥ 500 ms) on any group tile opens a menu:
         • Mute for me / Unmute for me
         • Pin / Unpin
         • Remove from call  (host only, not self)
  ══════════════════════════════════════════════════════════════ */
  function _showTileMenu(tile, event) {
    $("_tileMenu")?.remove();
    const userId = tile.dataset.userId;
    const name   = qs(".group-call-name", tile)?.textContent?.replace(" 🔇","") || "Participant";
    const isMe   = userId === currentUser?.uid;
    const isHost = activeCall?.fromUserId === currentUser?.uid;
    const isPinned = _pinnedUid === userId;
    const audio  = tile.querySelector("audio");

    const items = [];
    if (!isMe) items.push({
      label: audio?.muted ? "Unmute for me" : "Mute for me",
      action: () => _toggleMuteForMe(tile)
    });
    items.push({
      label: isPinned ? "Unpin" : "Pin to main view",
      action: () => pinGroupCallTile(userId)
    });
    if (!isMe && isHost) items.push({
      label: "Remove from call", danger: true,
      action: () => _removeParticipant(userId, name)
    });
    if (!items.length) return;

    const menu = document.createElement("div");
    menu.id = "_tileMenu";
    menu.className = "_tile-ctx-menu";
    menu.innerHTML = `<div class="_tcm-header">${escapeHtml(name)}</div>` +
      items.map((it, i) =>
        `<button class="_tcm-item${it.danger?" _tcm-danger":""}" data-i="${i}">${escapeHtml(it.label)}</button>`
      ).join("");
    menu.querySelectorAll("._tcm-item").forEach(b =>
      b.addEventListener("click", () => { items[+b.dataset.i].action(); menu.remove(); })
    );

    const shell = qs(".call-shell");
    shell?.appendChild(menu);

    // Position
    const sr = shell.getBoundingClientRect();
    const tr = tile.getBoundingClientRect();
    const mx = Math.min(Math.max(tr.left - sr.left + 8, 8), sr.width - 220);
    const my = Math.min(Math.max(tr.top  - sr.top  + 8, 8), sr.height - 160);
    menu.style.left = mx + "px";
    menu.style.top  = my + "px";

    const close = ev => { if (!menu.contains(ev.target)) { menu.remove(); document.removeEventListener("pointerdown", close); } };
    setTimeout(() => document.addEventListener("pointerdown", close), 80);
  }

  function _toggleMuteForMe(tile) {
    const audio = tile.querySelector("audio");
    if (!audio) return;
    audio.muted = !audio.muted;
    tile.classList.toggle("muted-for-me", audio.muted);
    const label = qs(".group-call-name", tile);
    if (label) {
      const base = label.dataset.base || label.textContent.replace(" 🔇","");
      label.dataset.base = base;
      label.textContent  = audio.muted ? base + " 🔇" : base;
    }
    showToast(audio.muted ? "Muted for you" : "Unmuted", "info");
  }

  function _removeParticipant(userId, name) {
    if (!confirm(`Remove ${name} from the call?`)) return;
    if (!activeCall?.id) return;
    db.collection("calls").doc(activeCall.id).update({
      [`participantStates.${userId}`]: "removed"
    }).then(() => showToast(`${name} removed`))
      .catch(() => showToast("Could not remove participant", "error"));
  }

  /* ══════════════════════════════════════════════════════════════
     5.  TILE GESTURE WIRING
         Short tap → pin, long-press (≥ 500 ms) → context menu.
  ══════════════════════════════════════════════════════════════ */
  function _wireTileGestures(tile) {
    if (tile.dataset.cfpWired) return;
    tile.dataset.cfpWired = "1";

    let pressId = null;
    let didLong = false;

    tile.addEventListener("pointerdown", e => {
      didLong = false;
      pressId = setTimeout(() => { didLong = true; _showTileMenu(tile, e); }, 500);
    }, { passive: true });

    tile.addEventListener("pointerup", () => {
      clearTimeout(pressId);
      pressId = null;
      if (!didLong) pinGroupCallTile(tile.dataset.userId);
    });

    ["pointercancel","contextmenu"].forEach(ev =>
      tile.addEventListener(ev, () => { clearTimeout(pressId); pressId = null; })
    );
  }

  /* ══════════════════════════════════════════════════════════════
     6.  INCOMING VIDEO CALL: DUAL ACCEPT BUTTONS
         Audio-only  📞   Video  📹
  ══════════════════════════════════════════════════════════════ */
  function _enhanceIncomingUI(type) {
    const acceptBtn = $("acceptCallBtn");
    if (!acceptBtn) return;
    // Remove any previously injected audio-accept
    $("_acceptAudio")?.remove();
    if (type !== "video") return;

    // Style existing button as "Answer with Video"
    acceptBtn.title = "Answer with video";
    acceptBtn.setAttribute("aria-label", "Answer with video");
    acceptBtn.dataset.controlLabel = "VIDEO";
    acceptBtn.innerHTML = "📹";
    acceptBtn.style.background = "#16a34a";
    acceptBtn.style.width  = "68px";
    acceptBtn.style.height = "68px";

    // Inject audio-only accept
    const aBtn = document.createElement("button");
    aBtn.id = "_acceptAudio";
    aBtn.className = "call-icon-btn";
    aBtn.innerHTML = "📞";
    aBtn.title = "Answer audio only";
    aBtn.setAttribute("aria-label", "Answer audio only");
    aBtn.dataset.controlLabel = "AUDIO";
    aBtn.style.cssText = "background:#1e7e5c;width:68px;height:68px;font-size:22px;";
    aBtn.addEventListener("click", () => {
      // Force voice-only accept
      window._cfpAudioOnlyAccept = true;
      activeCall && (activeCall.type = "voice");
      ($("acceptCallBtn"))?.click();
    });
    acceptBtn.parentNode?.insertBefore(aBtn, acceptBtn);

    // Label each button
    const wrap = acceptBtn.parentNode;
    if (wrap) {
      let lbl = wrap.querySelector("._dual-accept-label");
      if (!lbl) {
        lbl = document.createElement("div");
        lbl.className = "_dual-accept-label";
        lbl.innerHTML = `<span>Audio</span><span>Video</span>`;
        wrap.appendChild(lbl);
      }
    }
  }

  /* ══════════════════════════════════════════════════════════════
     7.  RAISED HAND
  ══════════════════════════════════════════════════════════════ */
  let _handRaised = false;

  function toggleRaisedHand() {
    _handRaised = !_handRaised;
    const btn = $("_raiseHandBtn");
    if (btn) { btn.classList.toggle("active", _handRaised); btn.title = _handRaised ? "Lower hand" : "Raise hand"; }
    // Sync to Firestore
    if (activeCall?.id && currentUser?.uid) {
      const update = _handRaised
        ? { [`raisedHands.${currentUser.uid}`]: true }
        : { [`raisedHands.${currentUser.uid}`]: firebase.firestore.FieldValue.delete() };
      db.collection("calls").doc(activeCall.id).update(update).catch(() => {});
    }
    // Show on my own tile
    _setHandBadge(currentUser?.uid, _handRaised);
    showToast(_handRaised ? "Hand raised ✋" : "Hand lowered", "info");
  }

  function _setHandBadge(uid, raised) {
    const tile = qs(`.group-call-tile[data-user-id="${uid}"]`, $("groupCallGrid"));
    if (!tile) return;
    let badge = tile.querySelector("._hand-badge");
    if (raised && !badge) { badge = document.createElement("span"); badge.className = "_hand-badge"; badge.textContent = "✋"; tile.appendChild(badge); }
    else if (!raised && badge) badge.remove();
  }

  // Listen for other participants raising hands
  let _handsUnsub = null;
  function _watchRaisedHands() {
    if (_handsUnsub || !activeCall?.id || !activeCall?.groupCall) return;
    _handsUnsub = db.collection("calls").doc(activeCall.id).onSnapshot(snap => {
      const hands = snap.data()?.raisedHands || {};
      // Reset all badges
      qsa(".group-call-tile").forEach(t => {
        const uid = t.dataset.userId;
        if (uid !== currentUser?.uid) _setHandBadge(uid, !!hands[uid]);
      });
    }, () => {});
  }

  /* ══════════════════════════════════════════════════════════════
     8.  PER-TILE NETWORK QUALITY BADGE
  ══════════════════════════════════════════════════════════════ */
  async function _updateGroupTileQuality() {
    if (!activeCall?.groupCall) return;
    for (const [uid, pc] of groupCallPeerConnections) {
      let rtt = null;
      try {
        const stats = await pc.getStats();
        stats.forEach(r => {
          if (r.type === "candidate-pair" && r.state === "succeeded" && r.nominated && r.currentRoundTripTime != null)
            rtt = r.currentRoundTripTime * 1000;
        });
      } catch {}
      const quality = rtt == null ? "unknown" : rtt < RTT_GOOD ? "good" : rtt < RTT_FAIR ? "fair" : "poor";
      const tile = qs(`.group-call-tile[data-user-id="${uid}"]`, $("groupCallGrid"));
      if (!tile) continue;
      let badge = tile.querySelector("._tile-nq");
      if (!badge) { badge = document.createElement("span"); badge.className = "_tile-nq"; tile.appendChild(badge); }
      badge.className = `_tile-nq _tnq-${quality}`;
      badge.textContent = quality === "good" ? "▐▐▐▐" : quality === "fair" ? "▐▐" : quality === "poor" ? "▐" : "";
    }
  }

  /* ══════════════════════════════════════════════════════════════
     9.  EXTRA CONTROL BUTTONS INJECTION
  ══════════════════════════════════════════════════════════════ */
  function _injectExtraButtons() {
    const controls = qs(".call-controls");
    if (!controls) return;

    // Raise hand (group only)
    if (!$("_raiseHandBtn")) {
      const btn = document.createElement("button");
      btn.id = "_raiseHandBtn";
      btn.className = "call-icon-btn";
      btn.innerHTML = "✋";
      btn.title = "Raise hand";
      btn.setAttribute("aria-label", "Raise hand");
      btn.dataset.controlLabel = "HAND";
      btn.style.display = activeCall?.groupCall ? "inline-flex" : "none";
      btn.addEventListener("click", toggleRaisedHand);
      const endBtn = $("endCallBtn");
      if (endBtn) controls.insertBefore(btn, endBtn);
      else controls.appendChild(btn);
    }
  }

  /* ══════════════════════════════════════════════════════════════
     HOOK INJECTION — non-breaking patches over existing functions
  ══════════════════════════════════════════════════════════════ */

  // Patch renderGroupCallTile → attach speaking indicator + wire gestures
  if (typeof window.renderGroupCallTile === "function") {
    const _orig = window.renderGroupCallTile;
    window.renderGroupCallTile = function(userId, name, stream, isLocal) {
      _orig.call(this, userId, name, stream, isLocal);
      const grid = $("groupCallGrid");
      if (!grid) return;
      const tile = qs(`.group-call-tile[data-user-id="${userId}"]`, grid);
      if (!tile) return;
      _wireTileGestures(tile);
      if (stream) _attachSpeaking(tile, stream, isLocal ? userId + "_local" : userId);
    };
  }

  // Patch setCallUi → start NQ monitor + inject extra buttons + dual accept
  if (typeof window.setCallUi === "function") {
    const _orig = window.setCallUi;
    window.setCallUi = function(opts = {}) {
      _orig.call(this, opts);
      const { mode, type } = opts;
      if (mode === "active") {
        setTimeout(() => {
          startNetworkQualityMonitor();
          _injectExtraButtons();
          const rhBtn = $("_raiseHandBtn");
          if (rhBtn) rhBtn.style.display = activeCall?.groupCall ? "inline-flex" : "none";
          _watchRaisedHands();
        }, 400);
      }
      if (mode === "incoming") {
        setTimeout(() => _enhanceIncomingUI(type), 150);
      }
      if (!["active","incoming","outgoing"].includes(mode)) {
        stopNetworkQualityMonitor();
      }
    };
  }

  // Patch cleanupGroupCallResources
  if (typeof window.cleanupGroupCallResources === "function") {
    const _orig = window.cleanupGroupCallResources;
    window.cleanupGroupCallResources = function() {
      stopAllSpeaking();
      stopNetworkQualityMonitor();
      unpinGroupCallTile();
      if (_handsUnsub) { _handsUnsub(); _handsUnsub = null; }
      _handRaised = false;
      _orig.call(this);
    };
  }

  // Patch stopLocalCallStream
  if (typeof window.stopLocalCallStream === "function") {
    const _orig = window.stopLocalCallStream;
    window.stopLocalCallStream = function() {
      stopAllSpeaking();
      stopNetworkQualityMonitor();
      unpinGroupCallTile();
      _orig.call(this);
    };
  }

  // Patch endActiveCall
  if (typeof window.endActiveCall === "function") {
    const _orig = window.endActiveCall;
    window.endActiveCall = function(...a) {
      stopAllSpeaking();
      stopNetworkQualityMonitor();
      unpinGroupCallTile();
      if (_handsUnsub) { _handsUnsub(); _handsUnsub = null; }
      _handRaised = false;
      return _orig.apply(this, a);
    };
  }

  // Patch endGroupCall
  if (typeof window.endGroupCall === "function") {
    const _orig = window.endGroupCall;
    window.endGroupCall = function(...a) {
      stopAllSpeaking();
      stopNetworkQualityMonitor();
      unpinGroupCallTile();
      if (_handsUnsub) { _handsUnsub(); _handsUnsub = null; }
      _handRaised = false;
      return _orig.apply(this, a);
    };
  }

  // Expose for debugging
  window._cfp = { pinGroupCallTile, unpinGroupCallTile, toggleRaisedHand,
                   startNetworkQualityMonitor, stopNetworkQualityMonitor };

  console.log("[CFP] WhatsApp-parity call feature pack loaded");
})();

/* ═══════════════════════════════════════════════════════════════════
   BACKGROUND EFFECTS SYSTEM — 2026
   Canvas pipeline: camera video → effect canvas → replaceTrack()
   Effects: Blur / Slight-blur / Virtual colour / Virtual image upload
   Segmentation: MediaPipe SelfieSegmentation (lazy CDN) with instant
   center-oval fallback so the button works immediately on first click.
   Works on web, PWA, and Capacitor Android (canvas captureStream).
═══════════════════════════════════════════════════════════════════ */
(function BgEffectsPack() {
  "use strict";

  /* ── state ─────────────────────────────────────────────────── */
  let _mode           = "off";    // 'off'|'blur'|'slight'|'color'|'image'
  let _canvas         = null;     // processing canvas (same res as camera)
  let _ctx            = null;
  let _blurCanvas     = null;     // offscreen blur layer
  let _blurCtx        = null;
  let _maskCanvas     = null;     // temp canvas for ML mask compositing
  let _maskCtx        = null;
  let _stream         = null;     // canvas.captureStream(30)
  let _raf            = null;     // animation-frame loop ID
  let _origTrack      = null;     // saved raw camera track
  let _segmenter      = null;     // MediaPipe SelfieSegmentation
  let _segReady       = false;
  let _bgColor        = "#1a2a3a";
  let _bgImg          = null;     // HTMLImageElement for virtual bg
  let _lastSegMask    = null;     // latest segmentation mask canvas
  let _segPending     = false;

  const FPS           = 30;
  const BLUR_HEAVY    = 20;       // px for 'blur' mode
  const BLUR_LIGHT    = 8;        // px for 'slight' mode

  /* ── canvas helpers ────────────────────────────────────────── */
  function _ensureCanvases(w, h) {
    if (!_canvas) {
      _canvas = document.createElement("canvas");
      _ctx    = _canvas.getContext("2d");
    }
    if (!_blurCanvas) {
      _blurCanvas = document.createElement("canvas");
      _blurCtx    = _blurCanvas.getContext("2d");
    }
    if (!_maskCanvas) {
      _maskCanvas = document.createElement("canvas");
      _maskCtx    = _maskCanvas.getContext("2d");
    }
    if (_canvas.width !== w || _canvas.height !== h) {
      _canvas.width  = _blurCanvas.width  = _maskCanvas.width  = w || 640;
      _canvas.height = _blurCanvas.height = _maskCanvas.height = h || 480;
    }
  }

  /* ── MediaPipe lazy-load ───────────────────────────────────── */
  function _loadSegmenter() {
    if (_segmenter || _segPending) return;
    _segPending = true;

    const BASE = "https://cdn.jsdelivr.net/npm/@mediapipe/selfie_segmentation@0.1.1675465747/";
    const s = Object.assign(document.createElement("script"), {
      src: BASE + "selfie_segmentation.js",
      crossOrigin: "anonymous",
    });
    s.onload = async () => {
      try {
        _segmenter = new SelfieSegmentation({
          locateFile: f => BASE + f,
        });
        _segmenter.setOptions({ modelSelection: 1 }); // landscape model
        _segmenter.onResults(r => {
          _lastSegMask = r.segmentationMask;
        });
        await _segmenter.initialize();
        _segReady = true;
        console.log("[BgFX] MediaPipe segmentation ready");
      } catch (e) {
        console.warn("[BgFX] MediaPipe failed, using fallback:", e);
      }
    };
    s.onerror = () => console.warn("[BgFX] MediaPipe CDN load failed, using ellipse fallback");
    document.head.appendChild(s);
  }

  /* ── blur-only helper (no segmentation) ───────────────────── */
  function _drawBlurFallback(ctx, blurCtx, videoEl, w, h, blurPx) {
    // Step 1 — blurred background layer on blurCanvas
    blurCtx.filter = `blur(${blurPx}px)`;
    blurCtx.drawImage(videoEl, 0, 0, w, h);
    blurCtx.filter = "none";

    // Step 2 — draw blurred layer onto main canvas
    ctx.drawImage(_blurCanvas, 0, 0, w, h);

    // Step 3 — overlay clear frame clipped to a soft center ellipse
    //   (approx person region; no ML needed)
    ctx.save();
    const rX = w * 0.30;
    const rY = h * 0.48;
    const cX = w * 0.50;
    const cY = h * 0.48;

    // Build soft feather mask on maskCanvas
    const mc = _maskCtx;
    mc.clearRect(0, 0, w, h);
    const grad = mc.createRadialGradient(cX, cY, rX * 0.40, cX, cY, rX * 1.10);
    grad.addColorStop(0,    "rgba(0,0,0,1)");
    grad.addColorStop(0.72, "rgba(0,0,0,1)");
    grad.addColorStop(1,    "rgba(0,0,0,0)");
    mc.ellipse(cX, cY, rX * 1.10, rY * 1.10, 0, 0, Math.PI * 2);
    mc.fillStyle = grad;
    mc.fill();

    // Draw clear video onto mask canvas
    mc.globalCompositeOperation = "source-in";
    mc.drawImage(videoEl, 0, 0, w, h);
    mc.globalCompositeOperation = "source-over";

    // Composite masked clear frame onto the blurred background
    ctx.drawImage(_maskCanvas, 0, 0, w, h);
    ctx.restore();
  }

  /* ── ML-segmented blur ─────────────────────────────────────── */
  function _drawBlurML(ctx, blurCtx, videoEl, w, h, blurPx, mask) {
    // Step 1 — blurred background
    blurCtx.filter = `blur(${blurPx}px)`;
    blurCtx.drawImage(videoEl, 0, 0, w, h);
    blurCtx.filter = "none";
    ctx.drawImage(_blurCanvas, 0, 0, w, h);

    // Step 2 — clear person on top using ML mask
    const mc = _maskCtx;
    mc.clearRect(0, 0, w, h);
    mc.drawImage(videoEl, 0, 0, w, h);
    mc.globalCompositeOperation = "destination-in";
    mc.drawImage(mask, 0, 0, w, h);
    mc.globalCompositeOperation = "source-over";

    ctx.drawImage(_maskCanvas, 0, 0, w, h);
  }

  /* ── virtual background helper ─────────────────────────────── */
  function _drawVirtualBg(ctx, videoEl, w, h, mask) {
    // Background: color or image
    if (_mode === "image" && _bgImg) {
      const scaleX = w / _bgImg.naturalWidth;
      const scaleY = h / _bgImg.naturalHeight;
      const scale  = Math.max(scaleX, scaleY);
      const bw     = _bgImg.naturalWidth  * scale;
      const bh     = _bgImg.naturalHeight * scale;
      ctx.drawImage(_bgImg, (w - bw) / 2, (h - bh) / 2, bw, bh);
    } else {
      ctx.fillStyle = _bgColor;
      ctx.fillRect(0, 0, w, h);
    }

    // Overlay person
    const mc = _maskCtx;
    mc.clearRect(0, 0, w, h);
    mc.drawImage(videoEl, 0, 0, w, h);
    if (mask) {
      mc.globalCompositeOperation = "destination-in";
      mc.drawImage(mask, 0, 0, w, h);
      mc.globalCompositeOperation = "source-over";
    } else {
      // Fallback ellipse mask
      const tmp = mc.getImageData(0, 0, w, h);
      mc.clearRect(0, 0, w, h);
      const g = mc.createRadialGradient(w*.5,h*.48,w*.15, w*.5,h*.48,w*.32);
      g.addColorStop(0, "rgba(0,0,0,1)"); g.addColorStop(.8,"rgba(0,0,0,1)"); g.addColorStop(1,"rgba(0,0,0,0)");
      mc.ellipse(w*.5,h*.48,w*.32,h*.48,0,0,Math.PI*2);
      mc.fillStyle = g; mc.fill();
      mc.globalCompositeOperation = "source-in";
      mc.drawImage(videoEl, 0, 0, w, h);
      mc.globalCompositeOperation = "source-over";
    }
    ctx.drawImage(_maskCanvas, 0, 0, w, h);
  }

  /* ── main render loop ──────────────────────────────────────── */
  async function _loop() {
    if (_mode === "off") return;

    const localVideo = document.getElementById("localVideo");
    if (!localVideo || !localVideo.srcObject) {
      _raf = requestAnimationFrame(_loop);
      return;
    }

    const w = localVideo.videoWidth  || 640;
    const h = localVideo.videoHeight || 480;
    _ensureCanvases(w, h);

    const ctx     = _ctx;
    const blurCtx = _blurCtx;

    // Try to send to MediaPipe segmenter
    if (_segReady && _segmenter && !_segPending) {
      try {
        _segPending = true;
        await _segmenter.send({ image: localVideo });
        _segPending = false;
      } catch { _segPending = false; }
    }

    const mask = _lastSegMask;

    if (_mode === "blur") {
      if (mask) _drawBlurML(ctx, blurCtx, localVideo, w, h, BLUR_HEAVY, mask);
      else       _drawBlurFallback(ctx, blurCtx, localVideo, w, h, BLUR_HEAVY);
    } else if (_mode === "slight") {
      if (mask) _drawBlurML(ctx, blurCtx, localVideo, w, h, BLUR_LIGHT, mask);
      else       _drawBlurFallback(ctx, blurCtx, localVideo, w, h, BLUR_LIGHT);
    } else if (_mode === "color" || _mode === "image") {
      _drawVirtualBg(ctx, localVideo, w, h, mask);
    }

    _raf = requestAnimationFrame(_loop);
  }

  /* ── start / stop ──────────────────────────────────────────── */
  async function startBgEffect(mode) {
    if (mode === "off") { stopBgEffect(); return; }

    // Get local video element (camera feed, unprocessed)
    const localVideo = document.getElementById("localVideo");
    if (!localVideo) { showToast("No camera active", "error"); return; }

    // Save original camera track before first activation
    if (!_origTrack) {
      const tracks = (typeof localCallStream !== "undefined" ? localCallStream : null)?.getVideoTracks?.() || [];
      _origTrack = tracks[0] || null;
    }

    // If already running a different mode, just change mode
    if (_mode !== "off" && _raf) {
      _mode = mode;
      if (mode === "blur" || mode === "slight") _loadSegmenter();
      return;
    }

    _mode = mode;
    if (mode === "blur" || mode === "slight") _loadSegmenter();

    // Start canvas pipeline
    const w = localVideo.videoWidth  || 640;
    const h = localVideo.videoHeight || 480;
    _ensureCanvases(w, h);

    _stream = _canvas.captureStream(FPS);

    // Replace camera track in peer connection
    const newTrack = _stream.getVideoTracks()[0];
    if (newTrack) {
      try {
        if (typeof cameraSender !== "undefined" && cameraSender?.replaceTrack) {
          await cameraSender.replaceTrack(newTrack);
        }
        // Also for group call peer connections
        if (typeof groupCallPeerConnections !== "undefined") {
          groupCallPeerConnections.forEach(async pc => {
            const sender = pc.getSenders().find(s => s.track?.kind === "video");
            if (sender) await sender.replaceTrack(newTrack).catch(() => {});
          });
        }
      } catch (e) { console.warn("[BgFX] replaceTrack failed:", e); }
    }

    // Point localVideo to our canvas stream so the preview matches what others see
    localVideo.srcObject = _stream;
    localVideo.play?.().catch(() => {});

    // Start render loop
    _raf = requestAnimationFrame(_loop);
    console.log("[BgFX] started:", mode);
  }

  async function stopBgEffect() {
    if (_raf) { cancelAnimationFrame(_raf); _raf = null; }
    _mode = "off";
    _lastSegMask = null;

    // Restore original camera track
    if (_origTrack && typeof cameraSender !== "undefined") {
      try {
        if (cameraSender?.replaceTrack) await cameraSender.replaceTrack(_origTrack);
        if (typeof groupCallPeerConnections !== "undefined") {
          groupCallPeerConnections.forEach(async pc => {
            const sender = pc.getSenders().find(s => s.track?.kind === "video");
            if (sender && _origTrack) await sender.replaceTrack(_origTrack).catch(() => {});
          });
        }
      } catch {}
    }

    // Restore localVideo to original stream
    const localVideo = document.getElementById("localVideo");
    if (localVideo && typeof localCallStream !== "undefined" && localCallStream) {
      localVideo.srcObject = localCallStream;
      localVideo.play?.().catch(() => {});
    }

    _origTrack = null;
    if (_stream) { _stream.getTracks().forEach(t => t.stop()); _stream = null; }
    console.log("[BgFX] stopped");
  }

  /* ── UI: Effects Panel ─────────────────────────────────────── */
  function _showEffectsPanel() {
    document.getElementById("_bgFxPanel")?.remove();

    const panel = document.createElement("div");
    panel.id    = "_bgFxPanel";
    panel.className = "_bgfx-panel";
    panel.setAttribute("role", "dialog");
    panel.setAttribute("aria-label", "Background effects");
    panel.innerHTML = `
      <div class="_bgfx-header">
        <span>Background Effects</span>
        <button class="_bgfx-close" aria-label="Close">✕</button>
      </div>
      <div class="_bgfx-scroll">
        <div class="_bgfx-options">
          <button class="_bgfx-opt${_mode==="off"?" _bgfx-active":""}" data-mode="off">
            <span class="_bgfx-thumb _bgfx-thumb-off">🚫</span>
            <span>None</span>
          </button>
          <button class="_bgfx-opt${_mode==="slight"?" _bgfx-active":""}" data-mode="slight">
            <span class="_bgfx-thumb _bgfx-thumb-slight">🌫</span>
            <span>Slight blur</span>
          </button>
          <button class="_bgfx-opt${_mode==="blur"?" _bgfx-active":""}" data-mode="blur">
            <span class="_bgfx-thumb _bgfx-thumb-blur">🌁</span>
            <span>Blur</span>
          </button>
          <button class="_bgfx-opt _bgfx-colors-trigger" data-mode="_colors">
            <span class="_bgfx-thumb _bgfx-thumb-color" style="background:${_bgColor}"></span>
            <span>Colour</span>
          </button>
          <button class="_bgfx-opt${_mode==="image"?" _bgfx-active":""}" id="_bgfx-upload-btn" data-mode="image">
            <span class="_bgfx-thumb _bgfx-thumb-img">🖼</span>
            <span>My photo</span>
          </button>
        </div>
        <div class="_bgfx-color-swatches" id="_bgfxSwatches" style="display:none">
          ${["#1a1a2e","#16213e","#0f3460","#533483","#05445e","#189ab4","#1a3a1a","#2d4a1e",
             "#3d1a00","#4a0000","#1a0a2e","#2a2a2a","#0a0a0a","#ffffff"].map(c =>
            `<button class="_bgfx-swatch${_bgColor===c?" _bgfx-swatch-active":""}" data-color="${c}" style="background:${c}"></button>`
          ).join("")}
        </div>
      </div>`;

    const shell = document.querySelector(".call-shell") || document.body;
    shell.appendChild(panel);

    // Event: close
    panel.querySelector("._bgfx-close").onclick = () => panel.remove();

    // Event: mode buttons
    panel.querySelectorAll("._bgfx-opt[data-mode]").forEach(btn => {
      btn.addEventListener("click", async () => {
        const m = btn.dataset.mode;
        if (m === "_colors") {
          const sw = panel.querySelector("#_bgfxSwatches");
          sw.style.display = sw.style.display === "none" ? "flex" : "none";
          return;
        }
        if (m === "image") {
          _triggerImageUpload(panel);
          return;
        }
        panel.querySelectorAll("._bgfx-opt").forEach(b => b.classList.remove("_bgfx-active"));
        btn.classList.add("_bgfx-active");
        await startBgEffect(m);
        _updateEffectsBtnState();
      });
    });

    // Event: colour swatches
    panel.querySelectorAll("._bgfx-swatch").forEach(sw => {
      sw.addEventListener("click", async () => {
        _bgColor = sw.dataset.color;
        panel.querySelectorAll("._bgfx-swatch").forEach(s => s.classList.remove("_bgfx-swatch-active"));
        sw.classList.add("_bgfx-swatch-active");
        const colorOpt = panel.querySelector("[data-mode='_colors'] ._bgfx-thumb");
        if (colorOpt) colorOpt.style.background = _bgColor;
        panel.querySelectorAll("._bgfx-opt").forEach(b => b.classList.remove("_bgfx-active"));
        panel.querySelector("[data-mode='_colors']").classList.add("_bgfx-active");
        await startBgEffect("color");
        _updateEffectsBtnState();
      });
    });

    // Click outside → close
    setTimeout(() => {
      const close = e => {
        if (!panel.contains(e.target) && e.target.id !== "_bgEffectsBtn") {
          panel.remove();
          document.removeEventListener("pointerdown", close);
        }
      };
      document.addEventListener("pointerdown", close);
    }, 80);
  }

  function _triggerImageUpload(panel) {
    const input = Object.assign(document.createElement("input"), {
      type: "file", accept: "image/*"
    });
    input.onchange = e => {
      const file = e.target.files?.[0];
      if (!file) return;
      const url = URL.createObjectURL(file);
      const img = new Image();
      img.onload = async () => {
        _bgImg = img;
        panel.querySelectorAll("._bgfx-opt").forEach(b => b.classList.remove("_bgfx-active"));
        panel.querySelector("[data-mode='image']").classList.add("_bgfx-active");
        // Update thumbnail
        const th = panel.querySelector("._bgfx-thumb-img");
        if (th) { th.style.backgroundImage = `url(${url})`; th.style.backgroundSize = "cover"; th.textContent = ""; }
        await startBgEffect("image");
        _updateEffectsBtnState();
      };
      img.src = url;
    };
    input.click();
  }

  function _updateEffectsBtnState() {
    const btn = document.getElementById("_bgEffectsBtn");
    if (!btn) return;
    btn.classList.toggle("active", _mode !== "off");
    btn.title = _mode === "off" ? "Background effects" : `Effects: ${_mode} (tap to change)`;
  }

  /* ── inject Effects button into call controls ──────────────── */
  function _injectEffectsButton() {
    const controls = document.querySelector(".call-controls");
    if (!controls || document.getElementById("_bgEffectsBtn")) return;
    const btn = document.createElement("button");
    btn.id        = "_bgEffectsBtn";
    btn.className = "call-icon-btn";
    btn.innerHTML = "✨";
    btn.title     = "Background effects";
    btn.setAttribute("aria-label", "Background effects");
    btn.dataset.controlLabel = "EFFECTS";
    // Only show in video calls
    btn.style.display = (typeof currentCallType !== "undefined" && currentCallType === "video") ? "inline-flex" : "none";
    btn.addEventListener("click", _showEffectsPanel);
    // Insert before end-call button
    const endBtn = document.getElementById("endCallBtn");
    if (endBtn) controls.insertBefore(btn, endBtn);
    else controls.appendChild(btn);
  }

  /* ── hook into existing call system ───────────────────────── */
  // Show/hide effects button when call type changes
  const _origUpdateCtrl = window.updateCallControlState;
  if (typeof _origUpdateCtrl === "function") {
    window.updateCallControlState = function() {
      _origUpdateCtrl.call(this);
      const btn = document.getElementById("_bgEffectsBtn");
      if (btn) {
        btn.style.display = (typeof currentCallType !== "undefined" && currentCallType === "video") ? "inline-flex" : "none";
      }
    };
  }

  // Hook setCallUi to inject the button when call becomes active
  const _origSetCallUi = window.setCallUi;
  if (typeof _origSetCallUi === "function") {
    window.setCallUi = function(opts = {}) {
      _origSetCallUi.call(this, opts);
      if (opts.mode === "active") {
        setTimeout(_injectEffectsButton, 500);
      }
      // When call ends, stop effect and restore
      if (!["active","incoming","outgoing"].includes(opts.mode)) {
        stopBgEffect();
        document.getElementById("_bgFxPanel")?.remove();
      }
    };
  }

  // Clean up when call ends
  const _origEnd  = window.endActiveCall;
  const _origEndG = window.endGroupCall;
  const _origStop = window.stopLocalCallStream;

  if (typeof _origEnd === "function") {
    window.endActiveCall = function(...a) {
      stopBgEffect(); document.getElementById("_bgFxPanel")?.remove();
      return _origEnd.apply(this, a);
    };
  }
  if (typeof _origEndG === "function") {
    window.endGroupCall = function(...a) {
      stopBgEffect(); document.getElementById("_bgFxPanel")?.remove();
      return _origEndG.apply(this, a);
    };
  }
  if (typeof _origStop === "function") {
    window.stopLocalCallStream = function() {
      stopBgEffect();
      return _origStop.call(this);
    };
  }

  // Expose for debugging
  window._bgFx = { startBgEffect, stopBgEffect, mode: () => _mode };
  console.log("[BgFX] Background effects system loaded");
})();
/* ═══════════════════════════════════════════════════════════════════
   RESPONSIVE UI/UX FIX — JS PATCH v2 — June 2026
   Safe version: removed touchend preventDefault (was blocking clicks).
═══════════════════════════════════════════════════════════════════ */
(function ResponsiveUxPatch() {
  "use strict";

  /* ── 1. Install App button — show only in header, hide inline card ─ */
  (function patchInstallApp() {
    let deferredPrompt = null;

    function getInstallEls() {
      return Array.from(document.querySelectorAll("[data-install-app]"));
    }
    function showInstallBtn() {
      getInstallEls().forEach(el => {
        if (el.id === "installAppBtn") {
          el.style.display = "";
          el.removeAttribute("hidden");
        } else {
          el.style.display = "none";
          el.setAttribute("hidden", "");
        }
      });
    }
    function hideInstallBtn() {
      getInstallEls().forEach(el => {
        el.style.display = "none";
        el.setAttribute("hidden", "");
      });
    }

    window.addEventListener("beforeinstallprompt", e => {
      e.preventDefault();
      deferredPrompt = e;
      showInstallBtn();
    });
    window.addEventListener("appinstalled", () => {
      deferredPrompt = null;
      hideInstallBtn();
    });
    document.addEventListener("click", async e => {
      const btn = e.target.closest("[data-install-app]");
      if (!btn || !deferredPrompt) return;
      e.preventDefault();
      btn.disabled = true;
      try {
        await deferredPrompt.prompt();
        const { outcome } = await deferredPrompt.userChoice;
        if (outcome === "accepted") hideInstallBtn();
      } catch {}
      btn.disabled = false;
      deferredPrompt = null;
    });
  })();

  /* ── 2. Context menu viewport clamping ─────────────────────── */
  function clampMenuToViewport(el) {
    if (!el) return;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const r  = el.getBoundingClientRect();
    let left = parseFloat(el.style.left) || r.left;
    let top  = parseFloat(el.style.top)  || r.top;
    if (r.right  > vw - 8) left = Math.max(8, vw - r.width - 8);
    if (r.bottom > vh - 8) top  = Math.max(8, vh - r.height - 8);
    if (left < 8) left = 8;
    if (top  < 8) top  = 8;
    el.style.left   = left + "px";
    el.style.top    = top  + "px";
    el.style.right  = "auto";
    el.style.bottom = "auto";
  }

  const _menuSel = ".chat-context-menu,.message-context-menu,#chatContextMenu,#messageContextMenu";
  new MutationObserver(mutations => {
    mutations.forEach(m => {
      if (m.type === "attributes") {
        const el = m.target;
        if (el.matches && el.matches(_menuSel) &&
            getComputedStyle(el).display !== "none") {
          requestAnimationFrame(() => clampMenuToViewport(el));
        }
      }
    });
  }).observe(document.body, { subtree: true, attributes: true, attributeFilter: ["style", "class"] });

  /* ── 3. Long-press context menu on mobile (backup handler) ─── */
  let _pressTimer = null;
  document.addEventListener("touchstart", e => {
    const msg = e.target.closest(".message");
    if (!msg) return;
    _pressTimer = setTimeout(() => {
      const optBtn = msg.querySelector(".message-options-btn");
      if (optBtn) { optBtn.click(); }
    }, 500);
  }, { passive: true });
  ["touchend","touchmove","touchcancel"].forEach(ev =>
    document.addEventListener(ev, () => clearTimeout(_pressTimer), { passive: true })
  );

  console.log("[ResponsiveUxPatch v2] loaded");
})();
